#include <rdma/rdma_cma.h>
#include <netinet/in.h>

int rdma_check_ip_validity(__be32 addr) {
    struct rdma_cm_id *id;
    struct sockaddr_in sin;
    int ret;

    id = rdma_create_id(NULL, NULL, NULL, RDMA_UDP);
    if (!id)
        return -ENOMEM;

    memset(&sin, 0, sizeof(sin));
    sin.sin_family = AF_INET;
    sin.sin_addr = addr;
    sin.sin_port = htons(0); /* Use ephemeral port */

    ret = rdma_bind_addr(id, (struct sockaddr *)&sin);
    if (ret) {
        rdma_destroy_id(id);
        return ret;
    }

    /* If binding succeeded, assume the address is valid for RDMA */
    rdma_destroy_id(id);
    return 0;
}

