#include <rdma/rdma_cm.h>
#include <netinet/in.h>
#include <stdio.h>

int is_rdma_ip_valid(__be32 addr) {
    struct rdma_id *id;
    struct sockaddr_in sin;
    int ret;

    id = rdma_create_id(&rdma_event_handler, NULL, 0);
    if (!id)
        return -ENOMEM;

    memset(&sin, 0, sizeof(sin));
    sin.sin_family = AF_INET;
    sin.sin_addr = addr;

    ret = rdma_bind_addr(id, (struct sockaddr *)&sin);
    if (ret) {
        rdma_destroy_id(id);
        return ret;
    }

    // If the binding is successful, check for IB device support
    if (!(id->device->dev_type & RDMA_DRIVER_IB)) {
        rdma_destroy_id(id);
        return -ENODEV;
    }

    rdma_destroy_id(id);
    return 0;
}
